@php
    $matchesByDay = collect($weeklyFootball['matches'])->groupBy(fn (array $match) => $match['startsAt']->format('Y-m-d'));
    $matchCount = count($weeklyFootball['matches']) + count($weeklyFootball['mondayNightMatches'] ?? []);
    $dayClasses = 'days days--standard';
    $dayGroups = [];
    foreach (range(0, 6) as $offset) {
        $date = $weeklyFootball['weekStart']->copy()->addDays($offset);
        $dayGroups[] = ['date' => $date, 'label' => ucfirst($date->locale('nb')->translatedFormat('l j. F')), 'matches' => $matchesByDay->get($date->format('Y-m-d'), collect())];
    }
    if (($weeklyFootball['mondayNightMatches'] ?? []) !== []) {
        $dayGroups[] = ['date' => null, 'label' => 'Natt til mandag '.$weeklyFootball['weekEnd']->copy()->addDay()->format('d.m'), 'matches' => collect($weeklyFootball['mondayNightMatches'])];
    }
    $extendedColumnCount = $matchCount <= 12 ? 2 : 3;
    $extendedColumns = array_fill(0, $extendedColumnCount, []);
    $targetColumnWeight = (int) ceil(array_sum(array_map(fn (array $group) => max(1, $group['matches']->count()), $dayGroups)) / $extendedColumnCount);
    $column = 0;
    $columnWeight = 0;
    foreach ($dayGroups as $group) {
        $weight = max(1, $group['matches']->count());
        if ($column < $extendedColumnCount - 1 && $columnWeight > 0 && $columnWeight + $weight > $targetColumnWeight) {
            $column++;
            $columnWeight = 0;
        }
        $extendedColumns[$column][] = $group;
        $columnWeight += $weight;
    }
@endphp
